        "company": "Credit Acceptance는 신용등급이 낮은(서브프라임) 소비자 대상 중고차 구매자금을 딜러 네트워크를 통해 간접 대출·서비싱하는 전문 여신회사로, 매출은 할부계약 금융수익과 딜러 수수료에서 발생한다. 최근 3개 분기 매출성장률은 0.62%→1.56%→2.47%로 개선세지만 순이익은 55.49→27.75→-19.68(전년비 %)로 둔화·적자전환 흐름을 보였고, 영업이익률은 49~52% 밴드를 유지하고 있다. 2020년 시작된 multistate 조사와 2023년 뉴욕주 검찰총장(NYAG) 소송이라는 장기 규제 리스크가 CFPB의 2025년 4월 철수 이후에도 NYAG·41개주 차원에서 이어져 왔다.",
