        "category": 6,
        "ticker": "CROX",
        "company": "Crocs, Inc.는 클로그(clog) 슈즈를 핵심으로 한 Crocs 브랜드와 2022년 인수한 HEYDUDE 브랜드를 도매·직판(DTC) 채널로 판매하는 풋웨어 업체다. 최근 3개 분기 매출성장률이 2.62% → -1.69% → -3.25%(YoY)로 역성장 전환했고 영업이익률도 24.22% → 21.8% → 15.29%로 뚜렷이 축소되는 국면으로, 성장 둔화와 마진 압박이 동시에 진행 중이다. 컨센서스도 CY 매출성장 1.48%·NY 2.41%로 저성장을 반영하고 있다.",
        "volumeExplanation": "제공된 1차 자료(뉴스 7건·8-K 6건)에 이번 거래량 증가(VOL_X 2, 주간 거래량배수 1.77)를 설명할 실적 서프라이즈·가이던스 변화·파트너십·승인·CEO 교체 등 촉매성 뉴스가 없다. 뉴스는 전부 Zacks의 밸류주 비교·동종업종 대비 등락 기사이고, 가장 최근 8-K(2026-07-30, item 2.02 실적)는 이번 거래량 급증 시점과 무관하게 지나간 분기 실적 발표다. 추가 웹검색에서도 Piper Sandler 컨퍼런스 참석과 이사 1인의 소액(약 9.9만 달러) 내부자 매수만 확인됐을 뿐, 가격을 움직일 만한 애널리스트 목표가 변경이나 정책·산업 이벤트는 확인되지 않았다.",
